GRAMMAR = {
76:[("Rhythm and thought groups","French rhythm is organised around groups of words and phrase-final prominence, not English-style stress on every content word. Practise complete thought groups and avoid giving every syllable equal emphasis."),("Question intonation","A yes/no question may use rising intonation in conversation, while inversion or est-ce que provides grammatical structure. Intonation changes with certainty, politeness and whether the speaker is genuinely asking."),("Liaison and enchaînement","Liaison introduces a normally silent final consonant before a vowel in specified contexts; enchaînement links a pronounced final consonant to the next vowel. Neither should be applied mechanically everywhere."),("Vowel contrasts","Work on contrasts such as /y/ versus /u/, /e/ versus /ɛ/ and nasal vowels. Minimal pairs and recordings help; regional variation is real, so aim first for intelligibility and consistency."),("Expressive intonation","Pitch movement can signal continuation, surprise, reservation, irony or completion. Interpret it with words and context rather than assigning one fixed meaning to a contour."),("Accent and identity","Native-level communication does not require erasing one's accent. Prioritise intelligibility, stable sound contrasts, natural phrasing and listener awareness.")],
77:[("Quebec French is diverse","There is no single Quebec accent. Urban and rural speech, generations, communities and speaking situations vary. Avoid treating one speaker as representative of everyone."),("Acadian varieties","Acadian French includes several regional varieties with distinctive histories and features. Familiarity with one recording does not guarantee understanding every Acadian speaker."),("Canadian French outside Quebec","Franco-Ontarian, Western Canadian and other francophone communities have their own linguistic histories and patterns. Vocabulary and pronunciation reflect contact and local identity."),("Affrication and vowel patterns","Some Quebec varieties affricate /t/ and /d/ before high front vowels and glides; vowel realisations can also differ. These are systematic patterns, not random errors."),("Code-switching and borrowing","Speakers may shift languages or use borrowings depending on community, topic and audience. Analyse the communicative context rather than assuming all bilingual speech follows one pattern."),("Listening without stereotyping","Identify concrete sound or vocabulary cues, then use context. Do not infer a speaker's identity, education or competence from accent alone.")],
78:[("Proverbs and fixed syntax","Proverbs often have stable wording and rhythm. Learn the complete expression, its implication and the contexts where it sounds natural rather than translating each word literally."),("Idiomatic meaning","An idiom's meaning may not be predictable from its parts. Record an example sentence and its register alongside the translation."),("Register and regional reach","Some expressions are widely shared; others are old-fashioned, literary, regional or informal. Check audience and context before using them."),("Adapting an idiom","Do not change a fixed expression's preposition or article unless a recognised variant exists. If uncertain, use a neutral paraphrase."),("Proverbs as argument","A proverb can summarise a point, but it may oversimplify a complex issue. Introduce it as a perspective, not as proof."),("Cultural interpretation","The same expression can sound warm, ironic or dismissive depending on intonation and relationship. Interpret the whole interaction.")],
79:[("Near-synonyms are not interchangeable","Pertinent, approprié, adéquat and judicieux overlap but differ in what they evaluate. Compare authentic examples and collocations before substituting one for another."),("Denotation and connotation","Denotation is a core meaning; connotation adds associations or evaluation. A word can be technically accurate but socially or emotionally unsuitable."),("Collocation and lexical pattern","Words prefer particular partners. Develop vocabulary in phrases such as apporter une preuve, soulever une question and formuler une hypothèse."),("Precision versus ornament","Rare vocabulary is not automatically advanced. Select the simplest term that expresses the intended distinction accurately."),("False friends and semantic drift","A familiar-looking word may differ in meaning or usage. Verify uncertain terms in a reliable French dictionary and note example contexts."),("Revising repetition","Replace repetition only when the new word preserves meaning. Sometimes repeating a key term improves clarity and cohesion.")],
80:[("Information structure","French word order can place familiar information before new information. C'est… qui/que, fronting and cleft structures highlight a specific element: C'est cette décision qui pose problème."),("Negation and scope","Ne… que means 'only', not a general negation. Ne… plus, ne… jamais, ne… guère and ne… aucun express different limits; identify exactly what is being negated."),("Mood and speaker stance","Indicative, subjunctive and conditional choices can encode certainty, evaluation, distance or reported information. The choice depends on construction and intended stance."),("Register-sensitive syntax","Inversion, nominalisation and longer subordinate clauses may suit formal writing, but can sound heavy in conversation. Match syntax to audience and purpose."),("Ellipsis and emphasis","Omitted words can create speed or rhetorical force when the missing material is recoverable. Avoid ellipsis if it makes the sentence ambiguous."),("Ambiguity and punctuation","Punctuation guides grouping and interpretation but cannot repair unclear syntax by itself. Rewrite a sentence if two readings remain possible.")],
81:[("Build a defensible interpretation","State a focused thesis, define the problem and support each interpretive claim with textual evidence. Distinguish what the text says from what you infer."),("Intertextuality","A text may echo earlier works, myths, historical events or genres. Identify the allusion and explain how it changes the meaning; do not assume every resemblance is deliberate."),("Academic qualification","Use il semble que, on peut soutenir que and cette lecture suggère que to signal the strength and limits of an interpretation."),("Argument structure","A strong academic paragraph makes a claim, presents evidence, analyses it and links it to the thesis. Quotations need interpretation, not just insertion."),("Literary voice and form","Narrative voice, focalisation, rhythm, imagery and genre conventions shape a reader's experience. Analyse their effects together rather than as an isolated checklist."),("Source evaluation","Assess author expertise, publication context, evidence and limitations. Separate a primary text from commentary about that text.")],
82:[("Ethos, logos and pathos","Credibility, reasoning and emotion are persuasive resources. Use them responsibly: credibility requires transparency, reasoning requires evidence and emotional appeals should not manipulate."),("Anaphora and parallelism","Repeating a structure can create rhythm and emphasis. Use repetition deliberately; excessive repetition weakens rather than strengthens an argument."),("Antithesis and concession","Contrast can clarify a choice: Il ne s'agit pas de…, mais de…. Concession acknowledges a valid objection before explaining why the thesis still holds."),("Framing and audience","The order and vocabulary used to present an issue shape attention. Explain the frame and include relevant alternatives so persuasion does not become distortion."),("Evidence and rebuttal","Represent opposing positions fairly, respond to their strongest version and distinguish evidence from anecdote. Acknowledge uncertainty where it exists."),("Rhetorical restraint","A persuasive conclusion follows from the argument. Avoid inflated certainty, personal attacks and rhetorical questions that replace evidence.")],
83:[("Contractual precision","Define terms, scope, responsibilities, conditions and dates explicitly. For legal or regulated matters, language-learning examples are not a substitute for qualified professional advice."),("Negotiation strategy","Separate positions from underlying interests. Identify priorities, alternatives and possible trade-offs before proposing a package."),("Diplomatic escalation","State the issue, its impact and the action needed. Use neutral descriptions and documented facts rather than blame or emotional labels."),("Executive summaries","Lead with the decision or recommendation, then provide rationale, risks, costs and next steps. Put detail in supporting sections."),("Risk and conditional language","Distinguish confirmed obligations from forecasts and possibilities. Terms such as sous réserve de, susceptible de and le cas échéant must be used precisely."),("Cross-cultural communication","Do not assume one communication style represents all French-speaking workplaces. Clarify expectations, decision processes and preferred levels of directness.")],
84:[("Historical references need context","Explain when, where and why a reference matters. Avoid reducing complex events to a slogan or assuming every listener shares the same background knowledge."),("Collective memory and contested narratives","Communities may remember the same event differently. Attribute perspectives and distinguish documented facts from interpretations."),("French-Canadian histories","Quebec, Acadian and other francophone histories are related but distinct. Include regional and community context rather than treating Canada as culturally uniform."),("Indigenous histories and living communities","Discuss First Nations, Inuit and Métis peoples as distinct peoples with continuing communities and contemporary voices. Avoid presenting them only as part of the past."),("Cultural allusions in media","Recognise references to public figures, literature, music, institutions and events, but verify unfamiliar references before drawing conclusions."),("Respectful discussion","Use precise names and terms, acknowledge disagreement and avoid claiming to speak for a community.")],
85:[("Listen before rebutting","Restate the other person's argument accurately before challenging it. This demonstrates comprehension and prevents debate from becoming parallel monologues."),("Build a layered position","Separate your main claim, supporting reasons, assumptions and implications. Make the logical connection between each step explicit."),("Handle interruptions and turns","Use concise entry phrases, return to the central question and invite clarification. Strong interaction includes making space for others."),("Respond to counterexamples","Ask whether the example disproves the claim, limits it or reveals an exception. Adjust the scope of your thesis when the evidence requires it."),("Manage uncertainty","Distinguish what is known, probable, plausible and unknown. Intellectual precision is stronger than pretending certainty."),("Synthesis and closure","Summarise areas of agreement and disagreement, identify unresolved questions and state what evidence could move the discussion forward.")],
86:[("Literal and intended meaning","A joke may depend on a gap between literal wording and intended meaning. Identify the setup, the expectation and the reinterpretation that creates the effect."),("Homophones and ambiguity","French wordplay can use similar sounds, spelling or multiple senses. Explain both readings and why the surrounding context makes them available."),("Irony and understatement","A restrained phrase can communicate strong criticism or praise. Tone and shared knowledge determine whether the statement is ironic."),("Parody and satire","Parody imitates a style; satire uses humour to criticise behaviour, institutions or ideas. Analyse the target and the technique separately."),("Self-deprecation and social context","Self-deprecating humour can build rapport, but may be misunderstood across relationships and cultures. Avoid assuming every audience welcomes it."),("Translation limits","Some jokes cannot be translated directly because the sound, cultural reference or ambiguity disappears. Explain the mechanism or create a new equivalent rather than forcing a literal translation.")],
87:[("Follow the structure of a broadcast","Identify introduction, topic framing, interview turns, evidence, transitions and conclusion. This helps retain the argument even when individual words are missed."),("Distinguish reporting from commentary","Separate verifiable reporting, analysis, opinion and advertising. Notice attribution and the evidence used for each claim."),("Recognise spoken markers","Fillers, repairs, repetitions and discourse markers are normal in spontaneous speech. Use them to track how speakers plan and qualify ideas."),("Evaluate sources","Check who produced the content, its date, evidence, funding or editorial context and whether other reliable sources corroborate key claims."),("Accent and audio conditions","Background noise, compression, overlap and regional pronunciation affect comprehension. Replay short segments and use transcripts as a later checking tool."),("Summarise faithfully","Capture the central claim, supporting reasons, important caveats and speaker stance. Do not turn a nuanced discussion into a more certain claim.")],
88:[("Voice and intended reader","Choose narrator, point of view, tone and level of formality before drafting. A consistent voice helps readers understand the purpose and relationship."),("Structure at document level","Plan the progression of sections and paragraphs. Each paragraph should perform a clear function and connect to the larger argument or narrative."),("Sentence rhythm","Vary sentence length and structure to guide emphasis. Long sentences need clear internal organisation; short sentences can create impact when used selectively."),("Revision beyond proofreading","Revise ideas, order, transitions and emphasis before correcting individual grammar details. Read aloud to identify awkward rhythm and unclear references."),("Precision and concision","Remove redundant phrases while preserving necessary qualifications. Concision is not the same as deleting context that readers need."),("Genre conventions","A report, proposal, essay, story and professional email have different expectations. Follow the genre while making deliberate stylistic choices.")],
89:[("Adapt to unfamiliar situations","Clarify the goal, audience and relationship quickly. Select a suitable register and ask a concise question when expectations are unclear."),("Maintain interaction","Respond to what was actually said, develop the topic and invite the other person in. Avoid delivering a memorised monologue unrelated to the exchange."),("Repair misunderstandings","Acknowledge the problem, restate the intended meaning and check understanding. Repair is a sign of communicative control, not failure."),("Shift register smoothly","Move from informal conversation to formal explanation when the setting changes. Keep vocabulary, pronouns and sentence structure consistent with the new register."),("Manage complex topics","Define terms, qualify generalisations and use examples. Summarise periodically so the listener can follow a demanding discussion."),("Self-monitor strategically","Notice errors that affect meaning or register, but do not interrupt every sentence to correct minor slips. Prioritise communication and repair important issues.")],
90:[("Integrated comprehension","Identify explicit information, implied meaning, tone, argument structure and relevant cultural references across demanding audio and written material."),("Integrated production","Produce coherent, accurate and appropriately structured speech and writing for unfamiliar purposes and audiences."),("Interaction and mediation","Clarify, paraphrase, synthesise different viewpoints and help others reach shared understanding without distorting their positions."),("Lexical and grammatical precision","Choose exact vocabulary, collocations, tense, mood and sentence structures while avoiding unnecessary complexity."),("Register and cultural judgement","Recognise regional and social variation and adapt language respectfully to the setting, relationship and communicative purpose."),("C2 is flexible mastery","C2 does not mean knowing every word or having no accent. It means handling complex language flexibly, precisely and effectively, including when the situation is unfamiliar.")]
}
EXPRESSIONS = [
("À toutes fins utiles…","For your information / for good measure…","Introduces information that may be useful."),
("Il va sans dire que…","It goes without saying that…","Marks a point presented as self-evident; use sparingly."),
("Tout bien considéré…","All things considered…","Introduces a balanced conclusion."),
("À cet égard…","In this respect…","Focuses on one aspect of a discussion."),
("Cela étant posé…","Having established that…","Moves from a premise to the next point."),
("Il convient de distinguer…","It is important to distinguish…","Introduces a precise conceptual distinction."),
("Loin de se limiter à…","Far from being limited to…","Expands or reframes a subject."),
("En dernier ressort…","Ultimately…","Introduces the decisive consideration.")
]
APPLICATION = [
("Which statement best describes C2 pronunciation goals?",["Clear, flexible and intelligible speech with controlled phrasing","Erasing every trace of one's personal accent","Speaking as quickly as possible","Using liaison in every possible position"],0,"C2 prioritises intelligibility, flexibility and control, not accent erasure."),
("What is the safest approach to regional accent variation?",["Use specific listening evidence and avoid stereotypes","Assume one speaker represents a whole region","Treat unfamiliar pronunciation as incorrect","Infer a person's ability from their accent"],0,"Regional varieties are diverse; analyse concrete features and context."),
("How should a proverb be used in an argument?",["As an illustrative perspective, not proof","As a replacement for evidence","As a universal rule without exception","Only by translating each word literally"],0,"A proverb can illustrate a point but cannot establish a complex claim."),
("Which choice best demonstrates lexical precision?",["Choose a word whose meaning and collocation fit the context","Replace every common word with a rare synonym","Avoid repeating any key term","Choose the longest available expression"],0,"Precision depends on meaning, context and collocation."),
("What does ne…que express?",["Only; limitation","Never","No longer","Nobody"],0,"Ne…que is restrictive and means 'only'."),
("What supports a defensible literary interpretation?",["A focused claim supported by textual evidence","A plot summary alone","An unsupported guess about the author","A list of quotations without analysis"],0,"Interpretations need evidence and explanation."),
("Which is an ethical persuasive practice?",["Represent opposing arguments fairly","Hide relevant limitations","Use emotion instead of evidence","Attack the person rather than the idea"],0,"Fair representation and transparent evidence strengthen responsible persuasion."),
("What should a complex executive summary do?",["State the recommendation and key reasons clearly","Include every detail before the conclusion","Avoid naming the decision needed","Use unexplained technical terms"],0,"An executive summary foregrounds the decision, rationale and key risks."),
("How should contested historical narratives be discussed?",["Attribute perspectives and distinguish facts from interpretations","Present one memory as universal","Ignore community voices","Reduce events to slogans"],0,"Historical interpretation requires context and careful attribution."),
("What is a strong response to a counterexample?",["Assess whether it disproves, limits or qualifies the claim","Dismiss it immediately","Change the subject","Repeat the original claim louder"],0,"A counterexample may require refining the scope of an argument.")
]
def _build(lesson_id):
    vocab=[]
    for raw in VOCAB[lesson_id]:
        french,meaning,pronunciation,ipa=raw.split("|",3)
        vocab.append((french,meaning,pronunciation,ipa,f"Cette expression s'emploie selon le contexte et le registre. — This expression is used according to context and register."))
    grammar=GRAMMAR[lesson_id]
    exercises=[]
    for i,item in enumerate(vocab[:5]):
        options=[item[1],vocab[(i+1)%10][1],vocab[(i+2)%10][1],vocab[(i+3)%10][1]]
        exercises.append((f"What does « {item[0]} » mean?",options,0,f"« {item[0]} » means {item[1]}."))
    for i,item in enumerate(grammar[:5]):
        options=[item[1],grammar[(i+1)%6][1],grammar[(i+2)%6][1],grammar[(i+3)%6][1]]
        exercises.append((f"Which principle best describes: {item[0]}?",options,0,item[1]))
    examples=[
        ("La précision du propos ne tient pas à la complexité des mots, mais à la justesse des distinctions.","The precision of an argument does not come from complex words, but from the accuracy of its distinctions.","A contrast structure highlights the central distinction."),
        ("Encore faut-il que les sources soient fiables et que les conclusions soient proportionnées aux données.","The sources must still be reliable and the conclusions proportionate to the data.","The subjunctive follows encore faut-il que."),
        ("Cette interprétation, pour séduisante qu'elle soit, ne rend pas compte de tous les éléments du texte.","As appealing as this interpretation may be, it does not account for all elements of the text.","Pour + adjective + que introduces a concessive subjunctive construction."),
        ("À défaut de pouvoir trancher, nous pouvons au moins préciser les limites de notre hypothèse.","If we cannot decide, we can at least clarify the limits of our hypothesis.","A precise alternative is offered without overstating certainty."),
        ("Le reportage donne la parole à plusieurs communautés, sans prétendre résumer leurs expériences respectives.","The report gives several communities a voice without claiming to summarise their respective experiences.","Sans + infinitive expresses the manner or limitation of the action."),
        ("Ce n'est pas tant la conclusion qui pose problème que le raisonnement qui y conduit.","It is not so much the conclusion that is problematic as the reasoning that leads to it.","A cleft-like contrast focuses attention on the reasoning.")
    ]
    conversations=[
        ("A high-level discussion",[("A","Je partage votre constat, mais je nuancerais l'interprétation que vous en tirez."),("B","Sur quel point précisément ?"),("A","Les données montrent une corrélation; elles ne suffisent pas, à elles seules, à établir un lien de causalité."),("B","C'est une distinction essentielle. Il faudrait donc examiner d'autres facteurs.")],"A: I share your observation, but I would qualify the interpretation you draw from it. B: In what respect exactly? A: The data show a correlation; on their own, they are not enough to establish a causal link. B: That is an essential distinction. We should therefore examine other factors."),
        ("Discussing language variation",[("A","J'ai écouté une entrevue avec une personne acadienne. Certaines voyelles m'ont surpris."),("B","C'est justement un bon rappel de la diversité des français parlés au Canada."),("A","Oui. Je préfère relever les caractéristiques précises plutôt que généraliser à partir d'un seul accent.")],"A: I listened to an interview with an Acadian speaker. Some vowels surprised me. B: That is a good reminder of the diversity of French spoken in Canada. A: Yes. I prefer to note specific features rather than generalise from one accent."),
        ("Negotiating a proposal",[("A","Nous pourrions accepter ce calendrier, sous réserve d'une clarification des responsabilités."),("B","Cette condition nous convient. En revanche, la date de livraison devra rester flexible."),("A","Dans ce cas, proposons un échéancier révisé et confirmons-le par écrit.")],"A: We could accept this schedule, subject to clarification of responsibilities. B: That condition works for us. However, the delivery date will need to remain flexible. A: In that case, let's propose a revised timeline and confirm it in writing.")
    ]
    speaking=[
        "Deliver a three-minute explanation of the lesson topic without notes. Organise the message and adapt your wording to a listener who is unfamiliar with the subject.",
        "Listen to two authentic Canadian French speakers from different communities. Record concrete differences in pronunciation, rhythm or vocabulary without ranking the speakers.",
        "Use five target expressions in original sentences, then explain their register and the contexts in which you would avoid them.",
        "Defend a position, present the strongest counterargument fairly and revise your conclusion if the evidence requires it.",
        "Summarise a demanding article, interview or podcast in two minutes, preserving the speaker's qualifications and uncertainty.",
        "Retell one idea in formal professional language, neutral conversation and informal speech. Keep the meaning stable while changing register.",
        "Practise the dialogues aloud, then continue each conversation with an unscripted follow-up question and response.",
        "Review your performance for precision, coherence, interaction, cultural awareness and register. Set one specific improvement goal."
    ]
    summary=[f"Develop flexible control of « {TITLES[lesson_id]} » across real communication contexts.","Prioritise precise meaning, coherent structure and appropriate register over unnecessary complexity.","Interpret regional variation, implication and cultural context without relying on stereotypes.","Use evidence, qualification and clear reasoning in demanding discussions and writing.","C2 mastery means communicating effectively and independently when language and situations are complex or unfamiliar."]
    return {"title":TITLES[lesson_id],"goal":GOALS[lesson_id],"vocab":vocab,"vocabulary":vocab,"grammar":grammar,"expressions":EXPRESSIONS,"examples":examples,"conversations":conversations,"exercises":exercises,"speaking":speaking,"summary":summary,"assessment":exercises+APPLICATION}
C2_LESSONS={lesson_id:_build(lesson_id) for lesson_id in range(76,91)}
